@push('scripts')<script>
const materialOptions=@json($materials->map(fn($m)=>['id'=>$m->id,'label'=>$m->name.' ('.$m->unit->label().')'])->values());
const operationOptions=@json($operations->map(fn($o)=>['id'=>$o->id,'label'=>$o->name])->values());
let mi={{ count($selectedItems) }}, oi={{ count($selectedOperations) }};
const opts=(items)=>'<option value="">اختر</option>'+items.map(x=>`<option value="${x.id}">${x.label}</option>`).join('');
document.getElementById('add-material').onclick=()=>document.getElementById('materials-body').insertAdjacentHTML('beforeend',`<tr><td><select name="items[${mi}][material_id]" class="form-select" required>${opts(materialOptions)}</select></td><td><input name="items[${mi}][quantity]" type="number" step="0.001" min="0.001" class="form-control" required></td><td><button type="button" class="btn btn-sm btn-outline-danger remove-row">حذف</button></td></tr>`),mi++;
document.getElementById('add-operation').onclick=()=>{document.getElementById('operations-body').insertAdjacentHTML('beforeend',`<tr><td class="sequence"></td><td><select name="operations[${oi}][manufacturing_operation_id]" class="form-select" required>${opts(operationOptions)}</select></td><td><input name="operations[${oi}][notes]" class="form-control"></td><td><button type="button" class="btn btn-sm btn-outline-danger remove-row">حذف</button></td></tr>`);oi++;renumber();};
document.addEventListener('click',e=>{if(e.target.classList.contains('remove-row')){e.target.closest('tr').remove();renumber();}}); function renumber(){document.querySelectorAll('#operations-body .sequence').forEach((x,i)=>x.textContent=i+1)}
const p=document.getElementById('product_id'),v=document.getElementById('product_variant_id'); function filterVariants(){[...v.options].forEach((o,i)=>{if(i)o.hidden=o.dataset.product!==p.value});if(v.selectedOptions[0]?.hidden)v.value='';} p.addEventListener('change',filterVariants);filterVariants();
</script>@endpush
